import React, { useState } from 'react';
import ProjectList from './ProjectList';

const Sidebar = () => {
  const [projects] = useState([
    { id: 1, name: 'Car Detection Model', status: 'completed', lastModified: '2 hours ago' },
    { id: 2, name: 'Dog Breed Classifier', status: 'training', lastModified: '1 day ago' },
    { id: 3, name: 'Traffic Sign Recognition', status: 'generating', lastModified: '3 days ago' },
    { id: 4, name: 'Fruit Classification', status: 'completed', lastModified: '1 week ago' },
  ]);

  return (
    <div className="h-full glass-effect border-r border-gray-200 flex flex-col">
      {/* Sidebar Header */}
      <div className="p-6 border-b border-gray-200">
        <h2 className="text-gray-900 text-lg font-semibold mb-2">Your Projects</h2>
        <p className="text-gray-600 text-sm">Create AI models with natural language</p>
      </div>

      {/* Projects List */}
      <div className="flex-1 overflow-y-auto">
        <ProjectList projects={projects} />
      </div>

      {/* Sidebar Footer */}
      <div className="p-6 border-t border-gray-200">
        <button className="w-full px-4 py-3 bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white rounded-lg font-medium transition-all">
          + New Project
        </button>
      </div>
    </div>
  );
};

export default Sidebar;
